from pathlib import Path
import json

ROOT = Path(__file__).parents[1]
NB_DIR = ROOT / "notebooks"
NB_DIR.mkdir(exist_ok=True)

def notebook(title, cells):
    return {
        "cells": [{"cell_type": "markdown" if kind == "md" else "code", "metadata": {}, "source": source.splitlines(True), **({"outputs": [], "execution_count": None} if kind == "code" else {})} for kind, source in cells],
        "metadata": {"kernelspec": {"display_name": "Python 3", "language": "python", "name": "python3"}, "language_info": {"name": "python", "version": "3.11"}, "title": title},
        "nbformat": 4,
        "nbformat_minor": 5,
    }

common = '''from pathlib import Path\nimport duckdb\nimport pandas as pd\nimport numpy as np\nimport matplotlib.pyplot as plt\nimport seaborn as sns\n\nROOT = Path.cwd().parent if Path.cwd().name == "notebooks" else Path.cwd()\nDATA = ROOT / "data"\ncon = duckdb.connect()\nsns.set_theme(style="whitegrid")\n'''

inventory = [
    ("md", "# SteelFlow: data inventory and relationship EDA\n\nThis notebook profiles the Parquet warehouse, confirms table grain, and documents the source-to-outcome flow before modeling."),
    ("code", common),
    ("code", "files = sorted(DATA.glob('*.parquet'))\nsummary = []\nfor path in files:\n    q = f\"SELECT count(*) AS rows FROM read_parquet('{path.as_posix()}')\"\n    rows = int(con.execute(q).fetchone()[0])\n    cols = con.execute(f\"DESCRIBE SELECT * FROM read_parquet('{path.as_posix()}')\").fetchdf()\n    summary.append({'table': path.stem, 'rows': rows, 'columns': len(cols)})\ncatalog = pd.DataFrame(summary).sort_values('rows', ascending=False)\ncatalog.head(20)"),
    ("code", "catalog.describe(include='all')"),
    ("code", "# Inspect key entities and event tables\nkey_tables = ['customers', 'products', 'factories', 'warehouses', 'customer_orders', 'customer_order_lines', 'outbound_shipments', 'delivery_outcomes', 'production_batches']\nfor name in key_tables:\n    path = DATA / f'{name}.parquet'\n    schema = con.execute(f\"DESCRIBE SELECT * FROM read_parquet('{path.as_posix()}')\").fetchdf()\n    print(f'\\n{name}: {len(schema)} columns')\n    display(schema[['column_name', 'column_type']])"),
    ("code", "# Row-count scale\nplt.figure(figsize=(12, 7))\nsns.barplot(data=catalog.head(20), y='table', x='rows', color='#2563eb')\nplt.title('Largest SteelFlow tables')\nplt.xlabel('Rows'); plt.ylabel('')\nplt.show()"),
    ("md", "## Data flow\n\nMaster tables describe entities. Transaction and event tables record orders, production, inventory, shipments, and payments. Outcome tables define supervised targets. Feature marts expose prediction-time variables and must be audited for leakage before use."),
]

demand = [
    ("md", "# SteelFlow: demand and sales forecasting EDA\n\nThe demand grain is one SKU at one demand centre on one target date. We validate coverage, seasonality, sparsity, and the supplied horizon feature marts."),
    ("code", common),
    ("code", "demand = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'daily_demand_by_sku_centre.parquet').as_posix()}')\").fetchdf()\ndemand['target_date'] = pd.to_datetime(demand['target_date'])\ndemand.info()"),
    ("code", "demand[['demand_kg','gross_requested_quantity_kg','accepted_order_quantity_kg']].describe(percentiles=[.01,.5,.95,.99])"),
    ("code", "daily = demand.groupby('target_date', as_index=False)['demand_kg'].sum()\nplt.figure(figsize=(14, 4)); sns.lineplot(data=daily, x='target_date', y='demand_kg'); plt.title('Total daily demand'); plt.show()"),
    ("code", "pivot = demand.pivot_table(index='target_date', columns='product_family', values='demand_kg', aggfunc='sum')\nplt.figure(figsize=(14, 6)); pivot.rolling(30).mean().plot(ax=plt.gca()); plt.title('30-day demand by product family'); plt.show()"),
    ("code", "h07 = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'forecast_features_horizon_07.parquet').as_posix()}')\").fetchdf()\nfor col in ['origin_date','feature_cutoff_date','target_date']:\n    h07[col] = pd.to_datetime(h07[col])\nprint(h07.groupby('split').agg(rows=('forecast_row_id','size'), origin_min=('origin_date','min'), origin_max=('origin_date','max'), target_mean=('target_demand_kg','mean')))"),
    ("code", "# Leakage checks: target must be after cutoff, and feature availability flags should explain missing lags\nassert (h07['target_date'] > h07['feature_cutoff_date']).all()\nassert (h07['target_date'] >= h07['origin_date']).all()\navailability = h07.filter(regex='available$').mean().sort_values()\navailability"),
    ("md", "## Modeling handoff\n\nThe supplied horizon tables already contain train/validation/test assignments and prediction-time features, so no integrated dataset is required for the first forecasting benchmark. The model notebook will use these tables directly and compare a seasonal-naive benchmark with tree ensembles."),
]

delivery = [
    ("md", "# SteelFlow: delivery, dispatch, and freight EDA\n\nThis notebook validates the late-delivery classification target and the freight-cost regression target, including class balance, time drift, and feature availability."),
    ("code", common),
    ("code", "late = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'dispatch_delay_model_dataset.parquet').as_posix()}')\").fetchdf()\nlate['dispatch_date'] = pd.to_datetime(late['dispatch_date'])\nlate['prediction_moment'] = pd.to_datetime(late['prediction_moment'])\nlate.groupby('split').agg(rows=('shipment_id','size'), late_rate=('target_is_late','mean'), min_date=('dispatch_date','min'), max_date=('dispatch_date','max'))"),
    ("code", "plt.figure(figsize=(8, 4)); sns.barplot(data=late, x='split', y='target_is_late', errorbar=None); plt.title('Late-delivery rate by split'); plt.ylabel('Rate'); plt.show()"),
    ("code", "late.groupby('route_type')['target_is_late'].agg(['count','mean']).sort_values('mean', ascending=False).head(15)"),
    ("code", "freight = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'freight_cost_model_dataset.parquet').as_posix()}')\").fetchdf()\nfreight['prediction_moment'] = pd.to_datetime(freight['prediction_moment'])\nfreight.groupby('split')['target_actual_billed_freight_cost_inr_ex_gst'].describe()"),
    ("code", "# Target leakage guardrails: prediction_moment precedes outcome by construction; exclude actual outcome fields from features.\nlate.filter(regex='target|actual|arrival|delay').columns.tolist()"),
    ("md", "## Modeling handoff\n\nThe supplied dispatch and freight marts are already aligned at shipment grain and include chronological split labels. They can be modeled directly after dropping target and post-outcome columns."),
]

models = [
    ("md", "# SteelFlow: baseline model comparison\n\nThis notebook compares multiple algorithms on late-delivery classification and demand forecasting. Metrics are calculated on the supplied time-based splits."),
    ("code", common),
    ("code", "from sklearn.compose import ColumnTransformer\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.metrics import average_precision_score, roc_auc_score, f1_score, mean_absolute_error, mean_squared_error\nfrom sklearn.linear_model import LogisticRegression, Ridge\nfrom sklearn.ensemble import RandomForestClassifier, HistGradientBoostingRegressor\n"),
    ("code", "late = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'dispatch_delay_model_dataset.parquet').as_posix()}')\").fetchdf()\nlate['dispatch_date'] = pd.to_datetime(late['dispatch_date'])\ntarget = 'target_is_late'\ndrop = [target, 'shipment_id', 'dispatch_timestamp', 'dispatch_date', 'prediction_moment', 'synthetic_record']\nX = late.drop(columns=[c for c in drop if c in late])\ny = late[target].astype(int)\ncat = X.select_dtypes(include=['object','bool']).columns.tolist()\nnum = [c for c in X.columns if c not in cat]\npre = ColumnTransformer([('num', Pipeline([('impute', SimpleImputer(strategy='median')), ('scale', StandardScaler())]), num), ('cat', Pipeline([('impute', SimpleImputer(strategy='most_frequent')), ('onehot', OneHotEncoder(handle_unknown='ignore'))]), cat)])\nmodels = {'logistic': LogisticRegression(max_iter=1000, class_weight='balanced'), 'random_forest': RandomForestClassifier(n_estimators=250, min_samples_leaf=5, class_weight='balanced', n_jobs=-1, random_state=42)}\nresults = []\nfor name, model in models.items():\n    pipe = Pipeline([('pre', pre), ('model', model)])\n    train, val, test = late['split'].eq('TRAIN'), late['split'].eq('VALIDATION'), late['split'].eq('TEST')\n    pipe.fit(X[train], y[train])\n    p = pipe.predict_proba(X[val])[:, 1]\n    results.append({'model': name, 'pr_auc_validation': average_precision_score(y[val], p), 'roc_auc_validation': roc_auc_score(y[val], p), 'f1_validation': f1_score(y[val], p >= .5)})\npd.DataFrame(results).sort_values('pr_auc_validation', ascending=False)"),
    ("md", "## Next model extension\n\nAdd the demand regression benchmark using `forecast_features_horizon_07`, `forecast_features_horizon_14`, and `forecast_features_horizon_30`. Compare seasonal-naive lag features, Ridge, Random Forest, and gradient boosting with MAE, RMSE, and WAPE. Save only the selected pipeline and metrics after evaluation."),
]

ml_suite = [
    ("md", "# SteelFlow: ML experiment suite\n\nThis notebook compares multiple algorithms for demand forecasting, late-delivery classification, and freight-cost regression. It uses the supplied time-based splits and records metrics in one results table."),
    ("code", common),
    ("code", "from sklearn.compose import ColumnTransformer\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import OneHotEncoder, StandardScaler\nfrom sklearn.impute import SimpleImputer\nfrom sklearn.metrics import average_precision_score, roc_auc_score, f1_score, mean_absolute_error, mean_squared_error\nfrom sklearn.linear_model import LogisticRegression, Ridge\nfrom sklearn.ensemble import RandomForestClassifier, RandomForestRegressor, HistGradientBoostingRegressor\nfrom sklearn.base import clone\n"),
    ("md", "## Late-delivery classification"),
    ("code", "late = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'dispatch_delay_model_dataset.parquet').as_posix()}')\").fetchdf()\ntarget = 'target_is_late'\ndrop = [target, 'shipment_id', 'dispatch_timestamp', 'dispatch_date', 'prediction_moment', 'synthetic_record']\nX = late.drop(columns=[c for c in drop if c in late]); y = late[target].astype(int)\ncat = X.select_dtypes(include=['object','bool']).columns.tolist(); num = [c for c in X.columns if c not in cat]\npre = ColumnTransformer([('num', Pipeline([('impute', SimpleImputer(strategy='median')), ('scale', StandardScaler())]), num), ('cat', Pipeline([('impute', SimpleImputer(strategy='most_frequent')), ('onehot', OneHotEncoder(handle_unknown='ignore'))]), cat)])\ntrain, val, test = late['split'].eq('TRAIN'), late['split'].eq('VALIDATION'), late['split'].eq('TEST')\nclassifiers = {'logistic': LogisticRegression(max_iter=1000, class_weight='balanced'), 'random_forest': RandomForestClassifier(n_estimators=250, min_samples_leaf=5, class_weight='balanced', n_jobs=-1, random_state=42)}\nclassification_results = []\nfor name, estimator in classifiers.items():\n    pipe = Pipeline([('pre', clone(pre)), ('model', estimator)])\n    pipe.fit(X[train], y[train]); prob = pipe.predict_proba(X[val])[:, 1]\n    classification_results.append({'task':'late_delivery','model':name,'pr_auc':average_precision_score(y[val],prob),'roc_auc':roc_auc_score(y[val],prob),'f1':f1_score(y[val],prob >= .5)})\npd.DataFrame(classification_results).sort_values('pr_auc', ascending=False)"),
    ("md", "## Freight-cost regression"),
    ("code", "freight = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'freight_cost_model_dataset.parquet').as_posix()}')\").fetchdf()\ntarget = 'target_actual_billed_freight_cost_inr_ex_gst'\ndrop = [target, 'freight_invoice_id', 'shipment_id', 'quote_timestamp', 'prediction_moment', 'synthetic_record']\nX = freight.drop(columns=[c for c in drop if c in freight]); y = freight[target]\ncat = X.select_dtypes(include=['object','bool']).columns.tolist(); num = [c for c in X.columns if c not in cat]\npre_reg = ColumnTransformer([('num', Pipeline([('impute', SimpleImputer(strategy='median')), ('scale', StandardScaler())]), num), ('cat', Pipeline([('impute', SimpleImputer(strategy='most_frequent')), ('onehot', OneHotEncoder(handle_unknown='ignore'))]), cat)])\ntrain, val = freight['split'].eq('TRAIN'), freight['split'].eq('VALIDATION')\nregressors = {'ridge': Ridge(alpha=10), 'random_forest': RandomForestRegressor(n_estimators=200, min_samples_leaf=5, n_jobs=-1, random_state=42)}\nregression_results = []\nfor name, estimator in regressors.items():\n    pipe = Pipeline([('pre', clone(pre_reg)), ('model', estimator)])\n    pipe.fit(X[train], y[train]); pred = pipe.predict(X[val])\n    regression_results.append({'task':'freight_cost','model':name,'mae':mean_absolute_error(y[val],pred),'rmse':mean_squared_error(y[val],pred)**0.5})\npd.DataFrame(regression_results).sort_values('mae')"),
    ("md", "## Demand forecasting benchmarks"),
    ("code", "h07 = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'forecast_features_horizon_07.parquet').as_posix()}')\").fetchdf()\nexclude = ['forecast_row_id','origin_date','prediction_moment','feature_cutoff_date','target_date','target_demand_kg','split','synthetic_record']\nX = h07.drop(columns=[c for c in exclude if c in h07]); y = h07['target_demand_kg']\ncat = X.select_dtypes(include=['object','bool']).columns.tolist(); num = [c for c in X.columns if c not in cat]\npre_dem = ColumnTransformer([('num', Pipeline([('impute', SimpleImputer(strategy='median'))]), num), ('cat', Pipeline([('impute', SimpleImputer(strategy='most_frequent')), ('onehot', OneHotEncoder(handle_unknown='ignore'))]), cat)])\ntrain, val = h07['split'].eq('TRAIN'), h07['split'].eq('VALIDATION')\nregressors = {'ridge': Ridge(alpha=10), 'random_forest': RandomForestRegressor(n_estimators=150, min_samples_leaf=5, n_jobs=-1, random_state=42), 'hist_gradient_boosting': HistGradientBoostingRegressor(max_iter=150, learning_rate=.08, l2_regularization=1.0, random_state=42)}\ndemand_results = []\nfor name, estimator in regressors.items():\n    pipe = Pipeline([('pre', clone(pre_dem)), ('model', estimator)])\n    pipe.fit(X[train], y[train]); pred = np.maximum(pipe.predict(X[val]), 0)\n    mae = mean_absolute_error(y[val], pred); wape = np.abs(y[val]-pred).sum()/np.abs(y[val]).sum()\n    demand_results.append({'task':'demand_horizon_07','model':name,'mae_kg':mae,'rmse_kg':mean_squared_error(y[val],pred)**0.5,'wape':wape})\npd.DataFrame(demand_results).sort_values('wape')"),
    ("code", "all_results = pd.concat([pd.DataFrame(classification_results), pd.DataFrame(regression_results), pd.DataFrame(demand_results)], ignore_index=True)\nall_results.to_csv(ROOT / 'artifacts' / 'ml_results.csv', index=False)\nall_results"),
    ("md", "## Selection rule\n\nSelect the model on validation metrics, then fit it on train plus validation and report the untouched test result. Keep the full preprocessing pipeline with the model so the deployment layer receives the same feature transformations used during evaluation."),
]

domains = [
    ("md", "# SteelFlow: commercial and supply-chain domain EDA\n\nThis notebook broadens the EDA beyond forecasting and delivery. Every section starts from a business grain, computes operational KPIs, and identifies useful prediction targets."),
    ("code", common),
    ("md", "## 1. Carrier and route performance\n\nGrain: one shipment or one carrier-route-month. We measure volume, lateness, cost, and service consistency."),
    ("code", "ship = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'outbound_shipments.parquet').as_posix()}')\").fetchdf()\nship['dispatch_date'] = pd.to_datetime(ship['dispatch_date'])\ncarrier_perf = ship.groupby('carrier_id').agg(shipments=('shipment_id','size'), weight_kg=('shipment_weight_kg','sum'), late_rate=('is_late','mean'), avg_delay_hours=('delay_hours_vs_promised','mean'), freight_per_kg=('quoted_freight_cost_inr','sum'))\ncarrier_perf['freight_per_kg'] = carrier_perf['freight_per_kg'] / carrier_perf['weight_kg'].clip(lower=1)\ncarrier_perf.sort_values(['late_rate','shipments'], ascending=[False,False]).head(20)"),
    ("code", "route_perf = ship.groupby(['route_id','route_type']).agg(shipments=('shipment_id','size'), late_rate=('is_late','mean'), avg_transit_hours=('actual_transit_hours','mean'), avg_cost_per_kg=('quoted_freight_cost_inr', lambda s: s.sum()))\nroute_perf.sort_values('late_rate', ascending=False).head(20)"),
    ("md", "## 2. Receivables, payment habits, and credit risk\n\nGrain: customer-month for behaviour and invoice for exposure. Candidate targets include overdue/default events, payment delay, and customer credit deterioration."),
    ("code", "ar = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'accounts_receivable.parquet').as_posix()}')\").fetchdf()\nprint(ar.columns.tolist())\ncustomer_behaviour = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'customer_payment_behaviour_monthly.parquet').as_posix()}')\").fetchdf()\ncustomer_behaviour.head()"),
    ("code", "# Inspect payment metrics and build a simple risk score from available behaviour fields\ncustomer_behaviour.describe(include='all').T.head(30)"),
    ("code", "credit = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'customer_credit_state.parquet').as_posix()}')\").fetchdf()\ncredit.columns.tolist()"),
    ("md", "## 3. Customer segments, habits, and churn-risk features\n\nChurn is not directly observed unless a future inactivity or default outcome exists. We therefore create an EDA proxy: recency, order frequency, spend/weight trend, cancellations, payment delay, disputes, and credit-state deterioration. The modeling target should be defined as inactivity in a future window, then validated against the synthetic business rules."),
    ("code", "orders = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'customer_orders.parquet').as_posix()}')\").fetchdf()\norders['order_date'] = pd.to_datetime(orders['order_date'])\ncustomer_rfm = orders.groupby('customer_id').agg(last_order=('order_date','max'), orders=('order_id','nunique'), revenue=('order_value_ex_gst','sum'), weight_kg=('ordered_weight_kg','sum'), avg_order_value=('order_value_ex_gst','mean'), avg_payment_delay=('expected_payment_delay_days_at_check','mean'))\nreference_date = orders['order_date'].max() + pd.Timedelta(days=1)\ncustomer_rfm['recency_days'] = (reference_date - customer_rfm['last_order']).dt.days\ncustomer_rfm.sort_values('recency_days', ascending=False).head(20)"),
    ("code", "customer_rfm[['recency_days','orders','revenue','weight_kg','avg_order_value','avg_payment_delay']].describe(percentiles=[.5,.9,.95,.99])"),
    ("md", "## 4. Inventory, suppliers, and warehouses\n\nInventory EDA should separate stock position from movements, then measure stockouts, turnover, coverage, and supplier concentration. These support reorder-demand, stockout-risk, supplier-delay, and warehouse-capacity models."),
    ("code", "fg = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'finished_goods_inventory_snapshots.parquet').as_posix()}')\").fetchdf()\nraw = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'raw_material_inventory_snapshots.parquet').as_posix()}')\").fetchdf()\nwh = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'warehouse_stock_snapshots.parquet').as_posix()}')\").fetchdf()\nprint('finished goods', fg.shape, fg.columns.tolist())\nprint('raw material', raw.shape, raw.columns.tolist())\nprint('warehouse', wh.shape, wh.columns.tolist())"),
    ("code", "sup = con.execute(f\"SELECT * FROM read_parquet('{(DATA/'supplier_material_month_performance.parquet').as_posix()}')\").fetchdf()\nprint(sup.columns.tolist())\nsup.head()"),
    ("code", "# Concentration and service-risk view\nif 'supplier_id' in sup and 'material_id' in sup:\n    print(sup.groupby('supplier_id').size().sort_values(ascending=False).head(15))\nif 'warehouse_id' in wh:\n    display(wh.groupby('warehouse_id').size().sort_values(ascending=False).head(15).to_frame('snapshot_rows'))"),
    ("md", "## EDA handoff\n\nThe next modeling stage can use: carrier late-risk, freight-cost estimation, customer future-inactivity risk, payment/default risk, stockout risk, supplier performance, and warehouse inventory forecasting. Before training, confirm each target is defined after the feature cutoff and split all data chronologically."),
]

for name, cells in [('01_inventory_eda.ipynb', inventory), ('02_demand_forecasting_eda.ipynb', demand), ('03_delivery_freight_eda.ipynb', delivery), ('04_baseline_model_comparison.ipynb', models)]:
    (NB_DIR / name).write_text(json.dumps(notebook(name, cells), indent=1), encoding='utf-8')
    print(NB_DIR / name)

(NB_DIR / '06_ml_experiment_suite.ipynb').write_text(json.dumps(notebook('06_ml_experiment_suite.ipynb', ml_suite), indent=1), encoding='utf-8')
print(NB_DIR / '06_ml_experiment_suite.ipynb')

(NB_DIR / '05_business_domain_eda.ipynb').write_text(json.dumps(notebook('05_business_domain_eda.ipynb', domains), indent=1), encoding='utf-8')
print(NB_DIR / '05_business_domain_eda.ipynb')
